let date=iso(new Date()),data={},filter='all',query='',uomFilter='all';
const cache=new Map(),dirty=new Set(),storageErrors=new Map(),blocked=new Set();
let armedDate=null,clearTimer;

function normalize(raw){
  if(!raw||typeof raw!=='object'||Array.isArray(raw))throw Error('Invalid saved data');
  const modern=Object.hasOwn(raw,'version');
  if(modern&&(raw.version!==2||!raw.records||typeof raw.records!=='object'||Array.isArray(raw.records)))throw Error('Unknown saved format');
  const records=modern?raw.records:raw,out={};
  for(const [key,r] of Object.entries(records)){
    const id=modern?key:(/^\d+$/.test(key)?'stock-'+padId(Number(key)+1):null);
    if(!id||!/^stock-\d{3}$/.test(id)||!r||typeof r!=='object'||Array.isArray(r))throw Error('Invalid saved row');
    out[id]={};
    for(const k of ['a','s','r'])if(r[k]!=null){if(!['string','number'].includes(typeof r[k]))throw Error('Invalid saved value');out[id][k]=String(r[k])}
  }
  return out;
}
function padId(n){return String(n).padStart(3,'0')}
function read(d){
  if(cache.has(d))return cache.get(d);
  let raw;
  try{raw=localStorage.getItem(KEY(d))}catch(e){blocked.add(d);storageErrors.set(d,'Cannot read saved entries; reload when browser storage is available');return {}}
  try{const result=raw===null?{}:normalize(JSON.parse(raw));cache.set(d,result);return result}
  catch(e){blocked.add(d);storageErrors.set(d,'Saved entries are damaged or unsupported; original data has been preserved');return {}}
}
function storageStatus(){
  const box=$('#storageStatus'),issues=[...storageErrors].map(([d,m])=>d+': '+m);
  box.hidden=!issues.length&&!dirty.size;
  $('#storageMessage').textContent=issues.join('. ')+(dirty.size?' Unsaved changes for '+dirty.size+' day(s) are kept in this tab. Retry saving or copy each day before closing.':'');
}
function save(d=date){
  if(d===date)cache.set(d,data);
  dirty.add(d);
  if(blocked.has(d)){storageStatus();return false}
  try{localStorage.setItem(KEY(d),JSON.stringify({version:2,records:cache.get(d)}));dirty.delete(d);storageErrors.delete(d);storageStatus();return true}
  catch(e){storageErrors.set(d,'Saving unavailable');storageStatus();return false}
}
function toast(m){const t=$('#toast');t.textContent=m;t.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>t.classList.remove('show'),2400)}
function num(v){
  if(v==null||String(v).trim()==='')return null;
  let t=String(v).trim();
  // A lone dot or comma is decimal; grouped Indonesian values require a comma.
  if(t.includes('.')&&t.includes(',')){
    if(!/^[+-]?\d{1,3}(?:\.\d{3})+,\d{1,4}$/.test(t))return null;
    t=t.replace(/\./g,'').replace(',','.');
  }else{if(!/^[+-]?(?:\d+(?:[.,]\d{1,4})?|[.,]\d{1,4})$/.test(t))return null;t=t.replace(',','.')}
  const n=Number(t);return Number.isFinite(n)&&Math.abs(n)<=1e10?n:null;
}
function calc(r){const a=num(r&&r.a),s=num(r&&r.s);if(a===null||s===null)return{diff:null,st:''};const diff=(Math.round(a*1e4)-Math.round(s*1e4))/1e4;return{diff,st:diff===0?'MATCH':'DO NOT MATCH'}}
function paint(r){const c=calc(data[r.dataset.i]);r.dataset.st=c.st;
  r.querySelectorAll('input.q').forEach(inp=>{const invalid=inp.value.trim()!==''&&num(inp.value)===null;inp.setAttribute('aria-invalid',String(invalid));inp.setCustomValidity(invalid?'Enter a valid number with up to four decimal places.':'')});
  r.querySelector('.df').textContent=c.diff===null?'':fmt.format(c.diff);
  r.querySelector('.st').innerHTML=c.st?'<span class="pill '+(c.st==='MATCH'?'ok':'bad')+'">'+c.st+'</span>':''}

function build(){
  $('#rows').innerHTML=ITEMS.map((it,i)=>'<div class="grid row" data-i="'+it[2]+'"><span class="n">'+(i+1)+'</span><span class="nm" id="item-'+it[2]+'">'+esc(it[0])+'</span><span class="u">'+esc(it[1])+'</span>'+
  ['a','s'].map(k=>'<label class="field" data-k="'+k+'"><span>'+(k==='a'?'Actual':'System')+'</span><input class="q" data-k="'+k+'" inputmode="decimal" enterkeyhint="next" aria-label="'+(k==='a'?'Actual':'System')+' — '+esc(it[0])+'"></label>').join('')+
  '<span class="df"></span><label class="field" data-k="r"><span>Remarks</span><input data-k="r" enterkeyhint="next" aria-label="Remarks — '+esc(it[0])+'"></label><span class="st"></span></div>').join('')}

function show(){
  data=read(date);
  const d=new Date(date+'T00:00:00');
  $('#date').value=date;
  $('#dow').textContent=d.toLocaleDateString('en-GB',{weekday:'long'});
  $('#mon').textContent=d.toLocaleDateString('en-GB',{month:'long',year:'numeric'});
  $('#dnum').textContent=pad(d.getDate());
  document.querySelectorAll('#rows .row').forEach(r=>{const v=data[r.dataset.i]||{};
    r.querySelectorAll('input').forEach(inp=>inp.value=v[inp.dataset.k]||'');paint(r)});
  stats();sortRows();filt();month();storageStatus();
}
function stats(){let c=0,m=0,b=0;document.querySelectorAll('#rows .row').forEach(r=>{const s=r.dataset.st;if(s){c++;s==='MATCH'?m++:b++}});
  const n=ITEMS.length,p=(x,t)=>t?Math.round(x/t*100)+'% of counted':'none counted yet';
  $('#sC').textContent=c;$('#sM').textContent=m;$('#sB').textContent=b;$('#sN').textContent=n-c;
  $('#sCs').textContent='of '+n+' items';$('#sMs').textContent=p(m,c);$('#sBs').textContent=p(b,c);$('#sNs').textContent=n-c?'still to count':'all counted';
  $('#chipT').textContent=c+' / '+n+' counted';$('#dot').className='dot '+(b?'bad':c?'ok':'');
  $('#sum').innerHTML='<span><b>'+c+'</b> counted, <b>'+m+'</b> match, <b>'+b+'</b> do not match</span>';const verifiedPercent=n?Math.round(c/n*100):0;
  const percentLabel=$('#verifiedPercent');if(percentLabel)percentLabel.textContent=verifiedPercent+'%';
  const verifiedLabel=$('#verifiedFraction');if(verifiedLabel)verifiedLabel.textContent=c+' of '+n+' items verified';
  const progressBar=$('#dashboardProgressFill');if(progressBar)progressBar.setAttribute('style','width:'+verifiedPercent+'%');
  const progressTrack=$('#dashboardProgressTrack');if(progressTrack)progressTrack.setAttribute('aria-valuenow',String(verifiedPercent))}
function filt(keepEditing=false){let shown=0;document.querySelectorAll('#rows .row').forEach(r=>{const st=r.dataset.st;
  const item=ITEMS.find(it=>it[2]===r.dataset.i);const ok=(filter==='all'||(filter==='bad'&&st==='DO NOT MATCH')||(filter==='none'&&!st))&&(uomFilter==='all'||String(item?.[1]||'').trim().toLowerCase()===uomFilter)&&(item?.[0]||'').toLowerCase().includes(query);
  const visible=ok||(keepEditing&&r.contains(document.activeElement));r.hidden=!visible;if(visible)shown++});$('#empty').hidden=shown>0}
function month(){const [y,m]=date.split('-').map(Number);const n=new Date(y,m,0).getDate();let full=0,bad=0,h='';
  for(let d=1;d<=n;d++){const k=y+'-'+pad(m)+'-'+pad(d);const rec=read(k);let c=0,b=0;
    ITEMS.forEach(it=>{const x=calc(rec[it[2]]);if(x.st){c++;if(x.st!=='MATCH')b++}});
    if(b)bad++;else if(c===ITEMS.length)full++;
    const cls=b?'bad':c===ITEMS.length?'ok':c?'part':'';
    h+='<button class="d '+cls+(k===date?' cur':'')+'" data-d="'+k+'" title="'+c+' counted, '+b+' do not match">'+d+'</button>'}
  $('#days').innerHTML=h;
  $('#mn').textContent=new Date(y,m-1,1).toLocaleDateString('en-GB',{month:'long',year:'numeric'})+': '+full+' days fully matched, '+bad+' with a variance. Dashed days are partly counted.'}
function disarm(){armedDate=null;clearTimeout(clearTimer);$('#clear').classList.remove('arm')}
function go(k){disarm();date=k;show()}
function shift(n){const d=new Date(date+'T00:00:00');d.setDate(d.getDate()+n);go(iso(d))}
let sortKey='no',sortDescending=false;
function sortValue(row,key){
 const item=ITEMS.find(it=>it[2]===row.dataset.i);
 const record=data[row.dataset.i]||{};
 if(key==='no')return ITEMS.indexOf(item);
 if(key==='name')return item?.[0]||'';
 if(key==='uom')return item?.[1]||'';
 if(key==='actual'||key==='system')return num(record[key==='actual'?'a':'s']);
 if(key==='difference')return calc(record).diff;
 if(key==='remarks')return record.r||'';
 if(key==='status')return row.dataset.st||'';
 return '';
}
function sortRows(){
 const host=$('#rows');if(!host)return;
 const rows=[...host.querySelectorAll('.row')];
 const collator=new Intl.Collator(undefined,{numeric:true,sensitivity:'base'});
 rows.sort((a,b)=>{
   const av=sortValue(a,sortKey),bv=sortValue(b,sortKey);
   const missingA=av===null||av===undefined||av==='';
   const missingB=bv===null||bv===undefined||bv==='';
   if(missingA!==missingB)return missingA?1:-1;
   let cmp=0;
   if(typeof av==='number'&&typeof bv==='number')cmp=av-bv;
   else cmp=collator.compare(String(av??''),String(bv??''));
   return (sortDescending?-cmp:cmp)||ITEMS.findIndex(it=>it[2]===a.dataset.i)-ITEMS.findIndex(it=>it[2]===b.dataset.i);
 });
 rows.forEach(row=>host.appendChild(row));
 const select=$('#itemSort');if(select)select.value=sortKey;
 const dir=$('#sortDirection');if(dir)dir.textContent=sortDescending?'↓ Descending':'↑ Ascending';
 document.querySelectorAll('.sort-head').forEach(b=>{const active=b.dataset.sort===sortKey;b.setAttribute('aria-pressed',String(active));b.querySelector('.sort-glyph').textContent=active?(sortDescending?'↓':'↑'):'↕'});
}
function setSort(key){if(sortKey===key)sortDescending=!sortDescending;else{sortKey=key;sortDescending=false}sortRows()}
document.querySelectorAll('.sort-head').forEach(b=>b.addEventListener('click',()=>setSort(b.dataset.sort)));
$('#itemSort').addEventListener('change',e=>{sortKey=e.target.value;sortDescending=false;sortRows()});
$('#sortDirection').addEventListener('click',()=>{sortDescending=!sortDescending;sortRows()});
function setFilter(f){filter=f;document.querySelectorAll('.f').forEach(x=>(x.classList.toggle('on',x.dataset.f===f),x.setAttribute('aria-pressed',String(x.dataset.f===f))));filt()}
function syncUomFilter(){
 const select=$('#uomFilter');if(!select)return;
 const current=uomFilter;
 const values=[...new Set(ITEMS.map(it=>String(it[1]||'').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,undefined,{numeric:true,sensitivity:'base'}));
 select.innerHTML='<option value="all">All UOMs</option>'+values.map(v=>'<option value="'+esc(v.toLowerCase())+'">'+esc(v)+'</option>').join('');
 uomFilter=values.some(v=>v.toLowerCase()===current)?current:'all';
 select.value=uomFilter;
}
$('#uomFilter')?.addEventListener('change',e=>{uomFilter=e.target.value;filt()});
syncUomFilter();


$('#rows').addEventListener('input',e=>{const inp=e.target,r=inp.closest('.row');if(!r)return;
  const i=r.dataset.i;data[i]=data[i]||{};data[i][inp.dataset.k]=inp.value;
  if(!data[i].a&&!data[i].s&&!data[i].r)delete data[i];
  save();paint(r);stats();month();filt(true)});
$('#rows').addEventListener('focusout',()=>setTimeout(()=>{sortRows();filt()},0));
$('#rows').addEventListener('keydown',e=>{const t=e.target;if(e.key!=='Enter'||t.tagName!=='INPUT')return;e.preventDefault();
  let nx;
  if(t.dataset.k==='a')nx=t.closest('.row').querySelector('input[data-k="s"]');
  else{let r=t.closest('.row').nextElementSibling;while(r&&r.hidden)r=r.nextElementSibling;nx=r&&r.querySelector('input[data-k="a"]')}
  if(nx){nx.focus();nx.scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})}});
$('#prev').onclick=()=>shift(-1);$('#next').onclick=()=>shift(1);$('#today').onclick=()=>go(iso(new Date()));
$('#date').onchange=e=>{if(e.target.value)go(e.target.value)};
$('#days').onclick=e=>{const b=e.target.closest('[data-d]');if(b)go(b.dataset.d)};
document.querySelectorAll('.f').forEach(b=>b.onclick=()=>setFilter(b.dataset.f));
document.querySelectorAll('.r[data-go]').forEach(b=>b.onclick=()=>{
  document.querySelectorAll('.r[data-go]').forEach(x=>x.classList.toggle('on',x===b));
  const g=b.dataset.go;if(g==='bad'){setFilter('bad');$('#listHead').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})}
  else{if(g==='listHead')setFilter('all');if(g==='monthCard')$('#monthDisclosure').open=true;$('#'+g).scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})}});
$('#q').oninput=e=>{query=e.target.value.trim().toLowerCase();filt()};
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#q').focus()}});
$('#copy').onclick=()=>{
  const lines=['Date\tNo\tItem Name\tUOM\tActual\tSystem\tDifference\tRemarks\tStatus'];
  ITEMS.forEach((it,i)=>{const r=data[it[2]]||{},c=calc(r);lines.push([date,i+1,excelText(it[0]),it[1],excelNumber(r.a),excelNumber(r.s),c.diff===null?'':fmtExport(c.diff),excelText(r.r),c.st].join('\t'))});
  const t=lines.join('\n');
  const fb=()=>{const a=document.createElement('textarea');a.value=t;document.body.appendChild(a);a.select();let ok=false;try{ok=document.execCommand('copy')}catch(e){}a.remove();toast(ok?'Copied. Paste into Excel.':'Copy was blocked by the browser.')};
  try{navigator.clipboard.writeText(t).then(()=>toast('Copied. Paste into Excel.'),fb)}catch(e){fb()}};
function excelText(v){const t=String(v??'').replace(/[\t\r\n]/g,' ');return /^[\s]*[=+@-]/.test(t)?"'"+t:t}
function fmtExport(n){return String(n).replace('.',',')}
function excelNumber(v){const n=num(v);return n===null?excelText(v):fmtExport(n)}
$('#clear').onclick=function(){
  if(armedDate===date){
    disarm();
    try{localStorage.removeItem(KEY(date))}catch(e){storageErrors.set(date,'Could not clear saved entries');storageStatus();toast('Clear failed. Entries have been kept.');return}
    cache.set(date,{});dirty.delete(date);blocked.delete(date);storageErrors.delete(date);show();toast('Day cleared');
  }else{disarm();armedDate=date;this.classList.add('arm');toast('Tap the bin again to clear '+date);clearTimer=setTimeout(disarm,3000)}
};
$('#retrySave').onclick=()=>{for(const d of [...dirty])save(d);storageStatus()};
window.addEventListener('beforeunload',e=>{if(dirty.size){e.preventDefault();e.returnValue=''}});
build();show();setFilter(filter);

// Refresh only after every pending edit has been persisted.
window.stockTakeCanRefresh=()=>{
  for(const d of [...dirty])save(d);
  return dirty.size===0;
};

window.STOCKTAKE_ITEMS=ITEMS;
window.stockTakeOpenDate=go;

window.stockTakeSetCatalog=items=>{
 if(!Array.isArray(items))return;
 ITEMS=items.filter(x=>Array.isArray(x)&&x.length===3&&/^stock-[0-9]{3,}$/.test(x[2]));
 window.STOCKTAKE_ITEMS=ITEMS;
 syncUomFilter();build();show();setFilter(filter);
};


// Merge live Counter entries from Neon into the Verifier table without
// replacing the verifier's in-progress System/Remarks edits.
window.stockTakeSyncActuals=(rows,forDate)=>{
 if(forDate!==date||!Array.isArray(rows))return;
 let changed=false;
 rows.forEach(item=>{
  const id=item.item_id;
  if(!id)return;
  const row=document.querySelector('#rows .row[data-i="'+CSS.escape(id)+'"]');
  const input=row?.querySelector('input[data-k="a"]');
  if(input&&document.activeElement===input)return;
  const next=item.actual==null?'':String(item.actual);
  const record=data[id]||(data[id]={});
  const current=record.a==null?'':String(record.a);
  if(current===next)return;
  if(next==='')delete record.a;else record.a=next;
  if(!Object.keys(record).length)delete data[id];
  if(input)input.value=next;
  if(row)paint(row);
  changed=true;
 });
 if(changed){
  cache.set(date,data);
  save(date);
  stats();
  month();
  sortRows();
  filt(true);
 }
};
